            "seccionRecientes",
            "productosRecientes",

            "seccionMarcas",
            "gridMarcas",

            "footerPrincipal",

            "panelCarrito",
            "panelCuenta",
            "panelComparador",

            "modalProducto",

            "pantallaCheckout",

            "modalPedidoInteligente",

            "btnAsistente",
            "ventanaAsistente",

            "bannerCookies",

            "btnVolverArriba",
