/* =========================================================
   🤖 ASISTENTE EMANUEL FARMA
   Búsqueda de productos + orientación general
========================================================= */

/* ============================================================
   🤖 EMANUEL IA AVANZADA — PARTE 1
   MOTOR DE COMPRENSIÓN DE TEXTO
============================================================ */

window.EmanuelMotor = (() => {

    "use strict";

    /* ---------------------------------------------------------
       NORMALIZAR TEXTO
    --------------------------------------------------------- */

    function normalizar(texto = "") {
        return String(texto)
            .normalize("NFD")
            .replace(/[\u0300-\u036f]/g, "")
            .toLowerCase()
            .replace(/[¿?¡!.,;:()[\]{}"'`]/g, " ")
            .replace(/\s+/g, " ")
            .trim();
    }

    /* ---------------------------------------------------------
       CORRECCIÓN DE ERRORES FRECUENTES
    --------------------------------------------------------- */

    const correcciones = {

        "ola": "hola",
        "hol": "hola",
        "holaa": "hola",
        "hl": "hola",

        "grasias": "gracias",
        "gracia": "gracias",
        "grax": "gracias",

        "q": "que",
        "k": "que",
        "ke": "que",

        "xq": "porque",
        "pq": "porque",
        "porq": "porque",

        "tngo": "tengo",
        "teng": "tengo",

        "duelee": "duele",
        "duel": "duele",
        "dolr": "dolor",

        "cabesa": "cabeza",
        "cavesa": "cabeza",

        "estomao": "estomago",
        "estomgo": "estomago",
        "estomago": "estomago",

        "diarreaa": "diarrea",
        "diarrea": "diarrea",

        "bomito": "vomito",
        "vomitoo": "vomito",
        "vomitos": "vomitos",

        "fievre": "fiebre",
        "fiebre": "fiebre",

        "tosss": "tos",

        "gripe": "gripe",
        "gripa": "gripe",

        "resfrio": "resfriado",
        "resfriado": "resfriado",

        "paracetamol": "paracetamol",
        "paracetanol": "paracetamol",
        "paracitamol": "paracetamol",
        "paracetanol": "paracetamol",

        "ibuprofeno": "ibuprofeno",
        "ibuprofeno": "ibuprofeno",
        "ibuprofeno": "ibuprofeno",

        "amoxicilina": "amoxicilina",
        "amoxilina": "amoxicilina",
        "amoxicilna": "amoxicilina",

        "presio": "precio",
        "precioo": "precio",

        "cuanto": "cuanto",
        "cuánto": "cuanto",

        "tinen": "tienen",
        "tieneen": "tienen",

        "stok": "stock",
        "stoc": "stock",

        "producto": "producto",
        "pruducto": "producto",

        "medicina": "medicina",
        "medecina": "medicina",

        "pastilla": "pastilla",
        "pastiya": "pastilla",

        "jarabe": "jarabe",
        "jarave": "jarabe",

        "direccion": "direccion",
        "direcion": "direccion",

        "horario": "horario",
        "orario": "horario",

        "yape": "yape",
        "yap": "yape"
    };


    function corregir(texto = "") {

        let palabras =
            normalizar(texto).split(" ");

        palabras = palabras.map(
            palabra =>
                correcciones[palabra] ||
                palabra
        );

        return palabras.join(" ");
    }


    /* ---------------------------------------------------------
       BUSCAR PALABRAS
    --------------------------------------------------------- */

    function contiene(texto, opciones = []) {

        const t = corregir(texto);

        return opciones.some(
            opcion =>
                t.includes(
                    normalizar(opcion)
                )
        );
    }


    /* ---------------------------------------------------------
       DETECTAR SALUDOS
    --------------------------------------------------------- */

    function esSaludo(texto) {

        return contiene(texto, [
            "hola",
            "buenos dias",
            "buenas tardes",
            "buenas noches",
            "hey",
            "holi",
            "que tal",
            "como estas"
        ]);
    }


    /* ---------------------------------------------------------
       DETECTAR DESPEDIDA
    --------------------------------------------------------- */

    function esDespedida(texto) {

        return contiene(texto, [
            "adios",
            "chau",
            "chao",
            "hasta luego",
            "nos vemos",
            "bye"
        ]);
    }


    /* ---------------------------------------------------------
       DETECTAR AGRADECIMIENTO
    --------------------------------------------------------- */

    function esGracias(texto) {

        return contiene(texto, [
            "gracias",
            "muchas gracias",
            "te agradezco",
            "genial gracias"
        ]);
    }


    /* ---------------------------------------------------------
       DETECTAR PREGUNTAS SOBRE EMANUEL
    --------------------------------------------------------- */

    function preguntaIdentidad(texto) {

        return contiene(texto, [
            "quien eres",
            "que eres",
            "como te llamas",
            "cual es tu nombre",
            "para que sirves",
            "que puedes hacer",
            "en que ayudas"
        ]);
    }


    /* ---------------------------------------------------------
       DETECTAR INTENCIONES
    --------------------------------------------------------- */

    function detectarIntencion(texto) {

        const t = corregir(texto);

        if (esSaludo(t))
            return "SALUDO";

        if (esDespedida(t))
            return "DESPEDIDA";

        if (esGracias(t))
            return "GRACIAS";

        if (preguntaIdentidad(t))
            return "IDENTIDAD";


        if (contiene(t, [
            "direccion",
            "donde queda",
            "ubicacion",
            "donde estan",
            "como llego"
        ]))
            return "DIRECCION";


        if (contiene(t, [
            "horario",
            "hora abren",
            "hora cierran",
            "estan abiertos",
            "atienden hoy",
            "cuando atienden"
        ]))
            return "HORARIO";


        if (contiene(t, [
            "yape",
            "forma de pago",
            "formas de pago",
            "como puedo pagar",
            "pagar"
        ]))
            return "PAGO";


        if (contiene(t, [
            "delivery",
            "envio",
            "envian",
            "llevan a domicilio"
        ]))
            return "DELIVERY";


        if (contiene(t, [
            "precio",
            "cuanto cuesta",
            "cuanto vale",
            "tienen",
            "stock",
            "disponible",
            "producto",
            "medicamento",
            "pastilla",
            "jarabe"
        ]))
            return "PRODUCTO";


        if (contiene(t, [
            "me duele",
            "dolor",
            "fiebre",
            "tos",
            "diarrea",
            "vomito",
            "vomitos",
            "mareo",
            "nauseas",
            "gripe",
            "resfriado",
            "congestion",
            "malestar",
            "enfermo",
            "enferma"
        ]))
            return "SALUD";


        if (
            t.startsWith("que es ") ||
            t.startsWith("que significa ") ||
            t.startsWith("explicame ") ||
            t.startsWith("como funciona ")
        )
            return "CONOCIMIENTO";


        return "DESCONOCIDA";
    }


    /* ---------------------------------------------------------
       EXTRAER EDAD SIN INVENTARLA
    --------------------------------------------------------- */

    function extraerEdad(texto) {

        const t = normalizar(texto);

        let match =
            t.match(
                /\b(?:tengo|edad|soy de)?\s*(\d{1,3})\s*(?:anos|año|años)\b/
            );

        if (!match)
            return null;

        const edad =
            Number(match[1]);

        if (
            edad < 1 ||
            edad > 120
        )
            return null;

        return edad;
    }


    /* ---------------------------------------------------------
       EXTRAER TEMPERATURA
       SOLO SI REALMENTE PARECE TEMPERATURA
    --------------------------------------------------------- */

    function extraerTemperatura(texto) {

        const t =
            normalizar(texto);

        const match =
            t.match(
                /\b(\d{2}(?:\.\d)?)\s*(?:grados|°c|celsius)\b/
            );

        if (!match)
            return null;

        const temperatura =
            Number(match[1]);

        if (
            temperatura < 30 ||
            temperatura > 45
        )
            return null;

        return temperatura;
    }


    /* ---------------------------------------------------------
       EXTRAER DURACIÓN
    --------------------------------------------------------- */

    function extraerDuracion(texto) {

        const t =
            normalizar(texto);

        const match =
            t.match(
                /\b(?:hace|desde hace|llevo)?\s*(\d+)\s*(dia|dias|hora|horas|semana|semanas)\b/
            );

        if (!match)
            return null;

        return {
            cantidad:
                Number(match[1]),

            unidad:
                match[2]
        };
    }


    /* ---------------------------------------------------------
       DETECTAR NEGACIÓN
    --------------------------------------------------------- */

    function esNegacion(texto) {

        const t =
            normalizar(texto);

        return [
            "no",
            "nop",
            "nope",
            "ninguno",
            "ninguna",
            "para nada"
        ].includes(t);
    }


    /* ---------------------------------------------------------
       DETECTAR AFIRMACIÓN
    --------------------------------------------------------- */

    function esAfirmacion(texto) {

        const t =
            normalizar(texto);

        return [
            "si",
            "sí",
            "sip",
            "claro",
            "correcto",
            "exacto"
        ].includes(t);
    }


    /* ---------------------------------------------------------
       DETECTAR SÍNTOMAS EXPLÍCITOS
       NO INVENTA SÍNTOMAS
    --------------------------------------------------------- */

    const sintomas = {

        fiebre: [
            "fiebre",
            "temperatura alta"
        ],

        tos: [
            "tos",
            "tosiendo"
        ],

        dolor_cabeza: [
            "dolor de cabeza",
            "me duele la cabeza"
        ],

        dolor_estomago: [
            "dolor de estomago",
            "me duele el estomago",
            "dolor abdominal"
        ],

        diarrea: [
            "diarrea"
        ],

        vomitos: [
            "vomito",
            "vomitos",
            "vomitando"
        ],

        nauseas: [
            "nausea",
            "nauseas"
        ],

        congestion: [
            "congestion",
            "nariz tapada"
        ],

        dolor_garganta: [
            "dolor de garganta",
            "me duele la garganta"
        ],

        mareo: [
            "mareo",
            "mareado",
            "mareada"
        ]

    };


    function detectarSintomas(texto) {

        const encontrados = [];

        const t =
            corregir(texto);

        Object.entries(
            sintomas
        ).forEach(
            ([nombre, palabras]) => {

                if (
                    palabras.some(
                        palabra =>
                            t.includes(
                                normalizar(palabra)
                            )
                    )
                ) {

                    encontrados.push(
                        nombre
                    );
                }
            }
        );

        return encontrados;
    }


    /* ---------------------------------------------------------
       ANALIZAR MENSAJE COMPLETO
    --------------------------------------------------------- */

    function analizar(texto) {

        const original =
            String(texto || "").trim();

        const limpio =
            normalizar(original);

        const corregido =
            corregir(original);

        return {

            original,

            limpio,

            corregido,

            intencion:
                detectarIntencion(
                    corregido
                ),

            edad:
                extraerEdad(original),

            temperatura:
                extraerTemperatura(
                    original
                ),

            duracion:
                extraerDuracion(
                    original
                ),

            sintomas:
                detectarSintomas(
                    original
                ),

            negacion:
                esNegacion(original),

            afirmacion:
                esAfirmacion(original)
        };
    }


    /* ---------------------------------------------------------
       EXPORTAR
    --------------------------------------------------------- */

    return {

        normalizar,
        corregir,
        contiene,
        analizar,
        detectarIntencion,
        detectarSintomas,
        extraerEdad,
        extraerTemperatura,
        extraerDuracion,
        esNegacion,
        esAfirmacion

    };

})();

