/* ============================================================
   🤖 EMANUEL IA AVANZADA — PARTE 3
   MOTOR DE RESPUESTAS + CONTEXTO + SALUD
============================================================ */

window.EmanuelCerebro = (() => {

    "use strict";

    /* ========================================================
       UTILIDADES
    ======================================================== */

    function motor() {
        return window.EmanuelMotor || null;
    }

    function memoria() {
        return window.EmanuelMemoria || null;
    }

    function textoSeguro(texto = "") {
        return String(texto || "").trim();
    }


    /* ========================================================
       RESPUESTAS VARIABLES
    ======================================================== */

    function elegir(lista) {

        if (!Array.isArray(lista) || !lista.length)
            return "";

        return lista[
            Math.floor(Math.random() * lista.length)
        ];
    }


    /* ========================================================
       SEÑALES DE ALERTA
    ======================================================== */

    function detectarUrgencia(texto) {

        const M = motor();

        if (!M)
            return false;

        const t = M.normalizar(texto);

        const alertas = [

            "no puedo respirar",
            "no puede respirar",
            "dificultad para respirar",
            "me falta el aire",

            "dolor fuerte en el pecho",
            "dolor intenso en el pecho",

            "me desmaye",
            "me desmayo",
            "desmayado",
            "desmayada",

            "convulsion",
            "convulsiones",

            "sangrado abundante",
            "sangro mucho",

            "inconsciente",
            "no responde",

            "no puedo despertar",
            "no puede despertar",

            "vomito sangre",
            "vomitando sangre",

            "heces con sangre",

            "labios morados",

            "confusion intensa"
        ];

        return alertas.some(
            alerta => t.includes(alerta)
        );
    }


    function respuestaUrgencia() {

        return `
            ⚠️ <strong>Esto puede requerir atención médica urgente.</strong>

            <br><br>

            Por lo que mencionas, es mejor buscar
            <strong>atención médica lo antes posible</strong>.

            <br><br>

            Si la persona está muy mal, tiene dificultad para respirar,
            pierde el conocimiento, convulsiona o presenta otro síntoma
            grave, busca ayuda de emergencia.

            <br><br>

            <strong>
            Consulta con un médico o con el personal de Emanuel Farma.
            </strong>
        `;
    }


    /* ========================================================
       RESPONDER UNA EDAD QUE EMANUEL ESTABA ESPERANDO
    ======================================================== */

    function responderDatoPendiente(resultado) {

        const MEM = memoria();

        if (!MEM || !resultado)
            return null;


        if (resultado.tipo === "EDAD") {

            const edad = resultado.valor;

            const siguiente =
                MEM.siguienteDatoSalud();

            if (siguiente === "DURACION") {

                MEM.esperar("DURACION");

                return `
                    Entendido 👍 Tienes
                    <strong>${edad} años</strong>.

                    <br><br>

                    ¿Desde cuándo tienes
                    ${MEM.listarSintomas() || "estos síntomas"}?

                    <br><br>

                    Por ejemplo:
                    “desde ayer” o “hace 2 días”.
                `;
            }


            if (
                MEM.mencionoFiebre() &&
                MEM.estado.salud.temperatura === null
            ) {

                MEM.esperar("TEMPERATURA");

                return `
                    Entendido 👍 Tienes
                    <strong>${edad} años</strong>.

                    <br><br>

                    Como mencionaste fiebre,
                    ¿te has medido la temperatura?

                    <br><br>

                    Si la sabes, puedes escribir por ejemplo:
                    <strong>38.2 grados</strong>.

                    Si no la sabes, responde simplemente:
                    <strong>no</strong>.
                `;
            }


            if (siguiente === "ALERGIAS") {

                MEM.esperar("ALERGIAS");

                return `
                    Gracias. Tengo en cuenta que tienes
                    <strong>${edad} años</strong>.

                    <br><br>

                    ¿Tienes alguna alergia conocida
                    a medicamentos?

                    <br><br>

                    Puedes responder simplemente:
                    <strong>sí</strong> o <strong>no</strong>.
                `;
            }

            return generarOrientacion();
        }


        /* ====================================================
           DURACIÓN
        ==================================================== */

        if (resultado.tipo === "DURACION") {

            const duracion =
                resultado.valor;

            if (
                MEM.estado.salud.edad === null
            ) {

                MEM.esperar("EDAD");

                return `
                    Entendido. Llevas aproximadamente
                    <strong>
                    ${duracion.cantidad} ${duracion.unidad}
                    </strong>
                    con los síntomas.

                    <br><br>

                    ¿Qué edad tienes?

                    <br><br>

                    Puedes responder:
                    <strong>“12 años”</strong>.
                `;
            }


            if (
                MEM.mencionoFiebre() &&
                MEM.estado.salud.temperatura === null
            ) {

                MEM.esperar("TEMPERATURA");

                return `
                    Gracias, eso ayuda a entender mejor
                    lo que estás contando.

                    <br><br>

                    Como mencionaste fiebre,
                    ¿sabes qué temperatura tienes?

                    <br><br>

                    Puedes escribir:
                    <strong>38 grados</strong>

                    o simplemente:
                    <strong>no</strong>.
                `;
            }


            if (
                MEM.estado.salud.alergias === null
            ) {

                MEM.esperar("ALERGIAS");

                return `
                    Entendido 👍

                    <br><br>

                    ¿Tienes alguna alergia conocida
                    a medicamentos?

                    <br><br>

                    Puedes responder simplemente
                    <strong>sí</strong> o <strong>no</strong>.
                `;
            }

            return generarOrientacion();
        }


        /* ====================================================
           TEMPERATURA
        ==================================================== */

        if (resultado.tipo === "TEMPERATURA") {

            const temperatura =
                Number(resultado.valor);

            if (temperatura >= 40) {

                return `
                    🌡️ Indicas una temperatura de
                    <strong>${temperatura} °C</strong>.

                    <br><br>

                    Una temperatura tan alta merece
                    <strong>valoración médica pronta</strong>,
                    especialmente si hay decaimiento intenso,
                    dificultad para respirar, confusión,
                    convulsiones u otros síntomas importantes.

                    <br><br>

                    <strong>
                    Consulta con un médico o con el personal
                    de Emanuel Farma.
                    </strong>
                `;
            }


            if (
                MEM.estado.salud.alergias === null
            ) {

                MEM.esperar("ALERGIAS");

                return `
                    Entendido. Registré la temperatura que
                    indicaste: <strong>${temperatura} °C</strong>.

                    <br><br>

                    ¿Tienes alguna alergia conocida
                    a medicamentos?

                    <br><br>

                    Puedes responder simplemente:
                    <strong>sí</strong> o <strong>no</strong>.
                `;
            }

            return generarOrientacion();
        }


        if (
            resultado.tipo ===
            "SIN_TEMPERATURA"
        ) {

            if (
                MEM.estado.salud.alergias === null
            ) {

                MEM.esperar("ALERGIAS");

                return `
                    Está bien, no voy a asumir una temperatura
                    que no hayas medido.

                    <br><br>

                    ¿Tienes alguna alergia conocida
                    a medicamentos?

                    <br><br>

                    Puedes responder:
                    <strong>sí</strong> o <strong>no</strong>.
                `;
            }

            return generarOrientacion();
        }


        /* ====================================================
           ALERGIAS
        ==================================================== */

        if (
            resultado.tipo ===
            "TIENE_ALERGIA"
        ) {

            return `
                Entendido.

                <br><br>

                ¿A qué medicamento o sustancia
                tienes alergia?
            `;
        }


        if (
            resultado.tipo ===
            "ALERGIAS"
        ) {

            return `
                Gracias. Tendré en cuenta únicamente
                la alergia que mencionaste:
                <strong>${resultado.valor}</strong>.

                <br><br>

                ${generarOrientacion()}
            `;
        }


        if (
            resultado.tipo ===
            "SIN_ALERGIAS"
        ) {

            return generarOrientacion();
        }


        return null;
    }


    /* ========================================================
       ORIENTACIÓN GENERAL
    ======================================================== */

    function generarOrientacion() {

        const MEM = memoria();

        if (!MEM)
            return null;

        const salud =
            MEM.estado.salud;

        const sintomas =
            MEM.listarSintomas();


        if (!sintomas) {

            return `
                🩺 Cuéntame qué síntoma o molestia tienes.

                <br><br>

                Por ejemplo:
                <strong>
                “Tengo dolor de garganta desde ayer”.
                </strong>

                <br><br>

                No voy a inventar síntomas que no hayas mencionado.
            `;
        }


        let respuesta = `
            🩺 Entiendo. Me has mencionado:
            <strong>${sintomas}</strong>.
        `;


        if (salud.duracion) {

            respuesta += `
                <br><br>

                Indicas que esto ocurre desde hace aproximadamente
                <strong>
                ${salud.duracion.cantidad}
                ${salud.duracion.unidad}
                </strong>.
            `;
        }


        if (salud.edad !== null) {

            respuesta += `
                <br><br>

                Edad indicada:
                <strong>${salud.edad} años</strong>.
            `;
        }


        if (salud.temperatura !== null) {

            respuesta += `
                <br><br>

                Temperatura indicada:
                <strong>${salud.temperatura} °C</strong>.
            `;
        }
 
        respuesta += `
        <br><br>
    
        <strong>💡 Orientación general:</strong>
        Estos síntomas pueden tener distintas causas, por lo que
        Emanuel no puede confirmar un diagnóstico solamente con
        esta conversación.
    `;
    
    
    /* =====================================================
       ORIENTACIONES SEGÚN LOS SÍNTOMAS MENCIONADOS
    ===================================================== */
    
    if (salud.sintomas.includes("diarrea")) {
    
        respuesta += `
            <br><br>
    
            💧 <strong>Si tienes diarrea:</strong>
            es importante reponer los líquidos que se pierden.
            Puedes beber líquidos y, cuando corresponda,
            soluciones de rehidratación oral.
    
            <br><br>
    
            Evita automedicarte con antibióticos o medicamentos
            para detener la diarrea sin orientación profesional,
            porque no son apropiados para todas las causas.
    
            <br><br>
    
            🚨 Busca atención médica si aparece sangre,
            signos de deshidratación, dolor intenso,
            empeoramiento importante o no puedes mantener líquidos.
        `;
    }
    
    
    if (salud.sintomas.includes("fiebre")) {
    
        respuesta += `
            <br><br>
    
            🌡️ <strong>Si tienes fiebre:</strong>
            mantente hidratado y controla tu temperatura.
    
            <br><br>
    
            Algunos medicamentos de venta libre se utilizan
            para reducir fiebre o aliviar dolor, pero la opción
            y la dosis dependen de la edad, presentación y otros
            factores. Consulta al personal de salud antes de usarlos.
        `;
    }
    
    
    if (salud.sintomas.includes("congestion")) {
    
        respuesta += `
            <br><br>
    
            👃 <strong>Si tienes congestión:</strong>
            mantener una buena hidratación y utilizar solución
            salina nasal puede ayudar a aliviar la molestia.
        `;
    }
    
    
    if (salud.sintomas.includes("dolor_garganta")) {
    
        respuesta += `
            <br><br>
    
            🫗 <strong>Si tienes dolor de garganta:</strong>
            beber líquidos y mantener una buena hidratación
            puede ayudar a aliviar la molestia.
        `;
    }
    
    
    respuesta += `
        <br><br>
    
        💊 <strong>¿Quieres buscar algo en Emanuel Farma?</strong>
    
        <br>
        Puedes preguntarme, por ejemplo:
    
        <br><br>
    
        • “Busca suero de rehidratación oral”
        <br>
        • “Busca paracetamol”
        <br>
        • “¿Cuánto cuesta el paracetamol?”
    
        <br><br>
    
        Te mostraré únicamente productos que existan
        en nuestro catálogo con su precio y disponibilidad.
    
        <br><br>
    
        <strong>
        Consulta con un médico o con el personal de Emanuel Farma
        antes de iniciar un medicamento para tratar estos síntomas.
        </strong>
    `;
        
        

       
       
        

       

        
        
        
        

        

         
         
    
        

    
    }


    /* ========================================================
       INICIAR CONSULTA DE SALUD
    ======================================================== */

    function responderSalud(
        texto,
        analisis
    ) {

        const MEM = memoria();

        if (!MEM)
            return null;


        if (detectarUrgencia(texto)) {
            return respuestaUrgencia();
        }


        /*
           actualizarDesdeMensaje ya registra SOLO
           síntomas realmente encontrados.
        */

        const sintomas =
            MEM.listarSintomas();


        if (!sintomas) {

            return `
                🩺 Puedo ayudarte con información general
                sobre salud.

                <br><br>

                Cuéntame exactamente qué molestia tienes.

                <br><br>

                Por ejemplo:
                <strong>
                “Tengo dolor de cabeza desde ayer”.
                </strong>

                <br><br>

                No confirmaré diagnósticos ni inventaré síntomas.
            `;
        }


        /* DURACIÓN */

        if (
            MEM.estado.salud.duracion === null
        ) {

            MEM.esperar("DURACION");

            return `
                Entiendo. Mencionaste:
                <strong>${sintomas}</strong>.

                <br><br>

                ¿Desde cuándo tienes
                ${MEM.estado.salud.sintomas.length > 1
                    ? "estos síntomas"
                    : "este síntoma"}?

                <br><br>

                Por ejemplo:
                <strong>“hace 2 días”</strong>.
            `;
        }


        /* EDAD */

        if (
            MEM.estado.salud.edad === null
        ) {

            MEM.esperar("EDAD");

            return `
                Entiendo. Mencionaste:
                <strong>${sintomas}</strong>.

                <br><br>

                ¿Qué edad tienes?

                <br><br>

                Puedes responder:
                <strong>“12 años”</strong>.
            `;
        }


        /* TEMPERATURA SOLO SI DIJO FIEBRE */

        if (
            MEM.mencionoFiebre() &&
            MEM.estado.salud.temperatura === null
        ) {

            MEM.esperar("TEMPERATURA");

            return `
                Como mencionaste
                <strong>fiebre</strong>,
                ¿sabes qué temperatura tienes?

                <br><br>

                Si la mediste, escribe por ejemplo:
                <strong>38.2 grados</strong>.

                <br><br>

                Si no la sabes, responde:
                <strong>no</strong>.
            `;
        }


        /* ALERGIAS */

        if (
            MEM.estado.salud.alergias === null
        ) {

            MEM.esperar("ALERGIAS");

            return `
                Gracias.

                <br><br>

                ¿Tienes alguna alergia conocida
                a medicamentos?

                <br><br>

                Puedes responder simplemente:
                <strong>sí</strong> o <strong>no</strong>.
            `;
        }


        return generarOrientacion();
    }


    /* ========================================================
       CONOCIMIENTO GENERAL BÁSICO
    ======================================================== */

    function conocimientoGeneral(texto) {

        const M = motor();

        if (!M)
            return null;

        const t =
            M.normalizar(texto);


        if (
            t.includes("que es la gripe") ||
            t.includes("que es gripe") ||
            t.includes("explicame la gripe")
        ) {

            return `
                🤧 La <strong>gripe</strong> es una infección
                respiratoria causada por virus influenza.

                <br><br>

                Puede producir fiebre, tos, dolor de garganta,
                dolores musculares, cansancio y otros síntomas,
                aunque no todas las personas presentan exactamente
                los mismos.

                <br><br>

                Si estás preguntando porque tienes síntomas,
                puedes contarme cuáles tienes y desde cuándo.

                <br><br>

                <strong>
                Consulta con un médico o con el personal de Emanuel Farma.
                </strong>
            `;
        }


        if (
            t.includes("que es la fiebre") ||
            t.includes("que es fiebre")
        ) {

            return `
                🌡️ La <strong>fiebre</strong> es un aumento
                de la temperatura corporal que puede aparecer
                como respuesta del organismo ante distintas causas,
                entre ellas algunas infecciones.

                <br><br>

                Si tienes una temperatura medida,
                puedes decirme cuánto marca.

                <br><br>

                <strong>
                Consulta con un médico o con el personal de Emanuel Farma.
                </strong>
            `;
        }


        if (
            t.includes("que es la diarrea") ||
            t.includes("que es diarrea")
        ) {

            return `
                🩺 La <strong>diarrea</strong> consiste en
                evacuaciones más líquidas o frecuentes de lo habitual.

                <br><br>

                Es importante prestar atención a la hidratación
                y a señales como sangre, empeoramiento importante
                o dificultad para beber líquidos.

                <br><br>

                <strong>
                Consulta con un médico o con el personal de Emanuel Farma.
                </strong>
            `;
        }


        if (
            t.includes("que es el paracetamol") ||
            t.includes("que es paracetamol")
        ) {

            return `
                💊 El <strong>paracetamol</strong> es un medicamento
                utilizado para aliviar dolor y reducir la fiebre.

                <br><br>

                La cantidad adecuada depende de factores como
                presentación, edad y otras condiciones, por lo que
                no debes asumir una dosis solamente por una respuesta
                del asistente.

                <br><br>

                Si quieres, también puedo buscar
                <strong>paracetamol en nuestro catálogo</strong>.

                <br><br>

                <strong>
                Consulta con un médico o con el personal de Emanuel Farma.
                </strong>
            `;
        }


        return null;
    }


    /* ========================================================
       RESPUESTA PRINCIPAL
    ======================================================== */

    function responder(texto) {

        const M = motor();
        const MEM = memoria();

        if (!M || !MEM) {

            console.warn(
                "Emanuel IA: Parte 1 o Parte 2 no está cargada."
            );

            return null;
        }


        const pregunta =
            textoSeguro(texto);

        if (!pregunta)
            return "Escribe una pregunta para poder ayudarte.";


        /* GUARDAR MENSAJE */

        MEM.guardar(
            "usuario",
            pregunta
        );


        /* ANALIZAR */

        const analisis =
            MEM.actualizarDesdeMensaje(
                pregunta
            );


        /* URGENCIA SIEMPRE PRIMERO */

        if (detectarUrgencia(pregunta)) {

            const respuesta =
                respuestaUrgencia();

            MEM.guardar(
                "emanuel",
                respuesta
            );

            return respuesta;
        }


        /* RESPUESTA A PREGUNTA ANTERIOR */

        const pendiente =
            MEM.interpretarRespuestaCorta(
                pregunta
            );


        if (pendiente) {

            const respuesta =
                responderDatoPendiente(
                    pendiente
                );

            if (respuesta) {

                MEM.guardar(
                    "emanuel",
                    respuesta
                );

                return respuesta;
            }
        }


        /* RESPUESTAS BÁSICAS */

        const basica =
            MEM.respuestaBasica(
                analisis
            );

        if (basica) {

            MEM.guardar(
                "emanuel",
                basica
            );

            return basica;
        }


        /* CONOCIMIENTO */

        const conocimiento =
            conocimientoGeneral(
                pregunta
            );

        if (conocimiento) {

            MEM.guardar(
                "emanuel",
                conocimiento
            );

            return conocimiento;
        }


        /* SALUD */

        if (
            analisis.intencion === "SALUD" ||
            (
                MEM.hayContextoSalud() &&
                analisis.sintomas.length > 0
            )
        ) {

            const respuesta =
                responderSalud(
                    pregunta,
                    analisis
                );

            if (respuesta) {

                MEM.guardar(
                    "emanuel",
                    respuesta
                );

                return respuesta;
            }
        }


        /*
           IMPORTANTE:
           Si Parte 3 no sabe responder,
           devuelve NULL.

           Así el asistente original todavía puede
           encargarse de productos, precios y stock.
        */

        return null;
    }


    /* ========================================================
       REINICIAR
    ======================================================== */

    function reiniciar() {

        const MEM =
            memoria();

        if (MEM)
            MEM.reiniciar();

        return `
            🔄 Conversación reiniciada.

            <br><br>

            ¿En qué puedo ayudarte?
        `;
    }


    /* ========================================================
       EXPORTAR
    ======================================================== */

    return {

        responder,
        detectarUrgencia,
        conocimientoGeneral,
        reiniciar

    };

})();


