/* ============================================================
   🤖 EMANUEL IA AVANZADA — PARTE 4
   PUENTE ENTRE CEREBRO AVANZADO + ASISTENTE ORIGINAL
============================================================ */

window.EmanuelPuente = (() => {

    "use strict";

    /* ========================================================
       GUARDAR EL CEREBRO AVANZADO
    ======================================================== */

    function responderAvanzado(pregunta) {

        if (
            !window.EmanuelCerebro ||
            typeof window.EmanuelCerebro.responder !== "function"
        ) {
            return null;
        }

        try {

            return window.EmanuelCerebro.responder(
                pregunta
            );

        } catch (error) {

            console.error(
                "❌ Error en EmanuelCerebro:",
                error
            );

            return null;
        }
    }


    /* ========================================================
       DETECTAR CONSULTAS COMERCIALES
       ESTAS LAS DEJAMOS AL BUSCADOR ORIGINAL
    ======================================================== */

    function esConsultaProducto(texto = "") {

        const t =
            window.EmanuelMotor
                ? window.EmanuelMotor.normalizar(texto)
                : String(texto).toLowerCase();


        const palabras = [

            "precio",
            "cuanto cuesta",
            "cuanto vale",

            "tienen",
            "tienes",
            "hay",

            "stock",
            "disponible",
            "disponibilidad",

            "busca",
            "buscar",
            "buscame",

            "producto",
            "medicamento",

            "paracetamol",
            "ibuprofeno",
            "amoxicilina",

            "pastilla",
            "jarabe",

            "codigo",
            "sku"
        ];


        return palabras.some(
            palabra =>
                t.includes(palabra)
        );
    }


    /* ========================================================
       RESPONDER
    ======================================================== */

    function responder(
        pregunta,
        respuestaOriginal
    ) {

        const texto =
            String(pregunta || "").trim();

        if (!texto)
            return "Escribe una pregunta para poder ayudarte.";


        /*
           PRODUCTOS:
           dejamos trabajar al asistente original porque
           ya conoce PRODUCTOS, precio y stock.
        */

        if (esConsultaProducto(texto)) {

            return respuestaOriginal();
        }


        /*
           PRIMERO INTENTAMOS CON EL NUEVO CEREBRO
        */

        const avanzada =
            responderAvanzado(texto);


        if (
            avanzada !== null &&
            avanzada !== undefined &&
            String(avanzada).trim() !== ""
        ) {

            return avanzada;
        }


        /*
           SI EL CEREBRO AVANZADO NO SABE,
           USAMOS EL ASISTENTE ORIGINAL
        */

        return respuestaOriginal();
    }


    /* ========================================================
       REINICIAR CONVERSACIÓN
    ======================================================== */

    function reiniciar() {

        if (
            window.EmanuelCerebro &&
            typeof window.EmanuelCerebro.reiniciar === "function"
        ) {

            return window.EmanuelCerebro.reiniciar();
        }


        return `
            🔄 Conversación reiniciada.
            <br><br>
            ¿En qué puedo ayudarte?
        `;
    }


    return {

        responder,
        esConsultaProducto,
        reiniciar

    };

})();


