    /* ========================================================
       10. VENTAS ÚLTIMOS 7 DÍAS
    ======================================================== */

    function ventas7Dias() {

        const resultado =
            [];

        const pedidos =
            obtenerPedidos();

        const hoy =
            new Date();

        for (
            let i = 6;
            i >= 0;
            i--
        ) {

            const dia =
                new Date(
                    hoy.getFullYear(),
                    hoy.getMonth(),
                    hoy.getDate() - i
                );

            let total =
                0;

            let cantidad =
                0;

            pedidos.forEach(
                pedido => {

                    if (
                        pedidoCancelado(
                            pedido
                        )
                    ) {
                        return;
                    }

                    const fecha =
                        fechaObjeto(
                            pedido.fecha ||
                            pedido.creado
                        );

                    if (!fecha) {
                        return;
                    }

                    if (
                        fecha.getDate() ===
                            dia.getDate() &&

                        fecha.getMonth() ===
                            dia.getMonth() &&

                        fecha.getFullYear() ===
                            dia.getFullYear()
                    ) {

                        total +=
                            numero(
                                pedido.total
                            );

                        cantidad++;
                    }
                }
            );

            resultado.push({

                fecha:
                    dia,

                etiqueta:
                    dia.toLocaleDateString(
                        "es-PE",
                        {
                            weekday:
                                "short"
                        }
                    )
                    .replace(
                        ".",
                        ""
                    ),

                total,

                cantidad
            });
        }

        return resultado;
    }

    /* ========================================================
       11. GRÁFICO
    ======================================================== */

    function htmlGraficoVentas() {

        const datos =
            ventas7Dias();

        const maximo =
            Math.max(
                1,
                ...datos.map(
                    item =>
                        item.total
                )
            );

        return `

            <div
                class="v6-barras"
            >

                ${datos.map(
                    item => {

                        const porcentaje =
                            item.total <= 0
                                ? 3
                                : Math.max(
                                    8,
                                    item.total /
                                    maximo *
                                    100
                                );

                        return `

                            <div
                                class="v6-barra-col"
                            >

                                <small>
                                    ${
                                        item.total > 0
                                            ? dinero(
                                                item.total
                                            )
                                            : ""
                                    }
                                </small>

                                <div
                                    class="v6-barra-area"
                                >

                                    <div
                                        class="v6-barra"
                                        style="
                                            height:
                                            ${porcentaje}%
                                        "
                                    ></div>

                                </div>

                                <strong>
                                    ${escapar(
                                        item.etiqueta
                                    )}
                                </strong>

                                <span>
                                    ${item.cantidad}
                                    ped.
                                </span>

                            </div>
                        `;
                    }
                ).join("")}

            </div>
        `;
    }

    /* ========================================================
       12. TOP PRODUCTOS
    ======================================================== */

    function productosMasVendidos() {

        const mapa =
            new Map();

        obtenerPedidos()
            .filter(
                pedido =>
                    !pedidoCancelado(
                        pedido
                    )
            )
            .forEach(
                pedido => {

                    const items =
                        Array.isArray(
                            pedido.productos
                        )
                            ? pedido.productos
                            : [];

                    items.forEach(
                        item => {

                            const clave =
                                item.id ||
                                item.sku ||
                                item.nombre;

                            if (!clave) {
                                return;
                            }

                            if (
                                !mapa.has(
                                    clave
                                )
                            ) {

                                mapa.set(
                                    clave,
                                    {
                                        nombre:
                                            item.nombre ||
                                            "Producto",

                                        cantidad:
                                            0,

                                        total:
                                            0
                                    }
                                );
                            }

                            const registro =
                                mapa.get(
                                    clave
                                );

                            const cantidad =
                                numero(
                                    item.cantidad
                                ) || 1;

                            registro.cantidad +=
                                cantidad;

                            registro.total +=
                                numero(
                                    item.precio
                                ) *
                                cantidad;
                        }
                    );
                }
            );

        return [
            ...mapa.values()
        ]
            .sort(
                (a, b) =>
                    b.cantidad -
                    a.cantidad
            )
            .slice(
                0,
                5
            );
    }

    /* ========================================================
       13. RENDER DASHBOARD
    ======================================================== */

