    function prepararInventarioExtra() {

        const panel =
            Q(
                '[data-admin-panel="inventario"]'
            );

        if (!panel) {
            return;
        }

        if (
            !ID(
                "v6InventarioHerramientas"
            )
        ) {

            const header =
                panel.querySelector(
                    ".admin-seccion-header"
                );

            const herramientas =
                document.createElement(
                    "div"
                );

            herramientas.id =
                "v6InventarioHerramientas";

            herramientas.className =
                "v6-herramientas";

            herramientas.innerHTML = `

                <input
                    id="v6BuscarInventario"
                    type="search"
                    placeholder="
                        Buscar inventario...
                    "
                >

                <select
                    id="v6FiltroInventario"
                >
                    <option value="todos">
                        Todo
                    </option>

                    <option value="disponible">
                        Disponible
                    </option>

                    <option value="bajo">
                        Stock bajo
                    </option>

                    <option value="agotado">
                        Agotados
                    </option>
                </select>

                <button
                    type="button"
                    data-v6-exportar-inventario
                >
                    Exportar CSV
                </button>

                <button
                    type="button"
                    data-v6-imprimir-inventario
                >
                    <i
                        class="fa-solid fa-print"
                    ></i>

                    Imprimir
                </button>
            `;

            header.after(
                herramientas
            );

            ID(
                "v6BuscarInventario"
            )
                ?.addEventListener(
                    "input",
                    renderTablaInventarioV6
                );

            ID(
                "v6FiltroInventario"
            )
                ?.addEventListener(
                    "change",
                    renderTablaInventarioV6
                );
        }

        renderTablaInventarioV6();
    }

    function renderTablaInventarioV6() {

        const tabla =
            ID(
                "tablaInventario"
            );

        if (!tabla) {
            return;
        }

        const busqueda =
            normalizar(
                ID(
                    "v6BuscarInventario"
                )?.value
            );

        const filtro =
            ID(
                "v6FiltroInventario"
            )?.value ||
            "todos";

        const lista =
            obtenerProductos()
                .filter(
                    producto => {

                        const texto =
                            normalizar([
                                producto.nombre,
                                producto.sku,
                                producto.codigoBarras,
                                producto.categoria
                            ].join(" "));

                        if (
                            busqueda &&
                            !texto.includes(
                                busqueda
                            )
                        ) {
                            return false;
                        }

                        const stock =
                            numero(
                                producto.stock
                            );

                        if (
                            filtro ===
                                "agotado" &&
                            stock > 0
                        ) {
                            return false;
                        }

                        if (
                            filtro ===
                                "bajo" &&
                            !(
                                stock > 0 &&
                                stock <= 5
                            )
                        ) {
                            return false;
                        }

                        if (
                            filtro ===
                                "disponible" &&
                            stock <= 5
                        ) {
                            return false;
                        }

                        return true;
                    }
                )
                .slice(
                    0,
                    300
                );

        if (!lista.length) {

            tabla.innerHTML = `

                <tr>
                    <td colspan="5">
                        No encontramos
                        productos.
                    </td>
                </tr>
            `;

            return;
        }

        tabla.innerHTML =
            lista.map(
                producto => {

                    const stock =
                        numero(
                            producto.stock
                        );

                    const estado =
                        stock <= 0
                            ? "Agotado"
                            : stock <= 5
                                ? "Stock bajo"
                                : "Disponible";

                    return `

                        <tr>

                            <td>
                                <strong>
                                    ${escapar(
                                        producto.nombre
                                    )}
                                </strong>

                                <small>
                                    ${escapar(
                                        producto.categoria ||
                                        ""
                                    )}
                                </small>
                            </td>

                            <td>
                                ${escapar(
                                    producto.sku ||
                                    producto.codigoBarras ||
                                    "—"
                                )}
                            </td>

                            <td>
                                <strong>
                                    ${stock}
                                </strong>
                            </td>

                            <td>
                                <span
                                    class="
                                        v6-stock-estado
                                        ${
                                            stock <= 0
                                                ? "agotado"
                                                : stock <= 5
                                                    ? "bajo"
                                                    : "ok"
                                        }
                                    "
                                >
                                    ${estado}
                                </span>
                            </td>

                            <td>

                                <div
                                    class="v6-stock-controles"
                                >

                                    <button
                                        data-v6-stock-menos="${escapar(
                                            producto.id
                                        )}"
                                    >
                                        −
                                    </button>

                                    <button
                                        data-v6-stock-ajustar="${escapar(
                                            producto.id
                                        )}"
                                    >
                                        Ajustar
                                    </button>

                                    <button
                                        data-v6-stock-mas="${escapar(
                                            producto.id
                                        )}"
                                    >
                                        +
                                    </button>

                                </div>

                            </td>

                        </tr>
                    `;
                }
            ).join("");
    }

    /* ========================================================
       18. CAMBIAR STOCK
    ======================================================== */

    function cambiarStock(
        productoId,
        cantidad,
        motivo = "Ajuste manual"
    ) {

        const producto =
            obtenerProductos()
                .find(
                    item =>
                        String(item.id) ===
                        String(productoId)
                );

        if (!producto) {

            notificar(
                "Producto no encontrado.",
                "error"
            );

            return;
        }

        const anterior =
            numero(
                producto.stock
            );

        const nuevo =
            Math.max(
                0,
                numero(cantidad)
            );

        producto.stock =
            nuevo;

        guardarMovimiento(
            producto,
            anterior,
            nuevo,
            motivo
        );

        renderTablaInventarioV6();

        App.v6RenderDashboard();

        notificar(
            `${producto.nombre}: stock ${anterior} → ${nuevo}`
        );
    }

    /* ========================================================
       19. PEDIDOS — CREAR CONTROLES
    ======================================================== */

    function prepararPedidos() {

        const panel =
            Q(
                '[data-admin-panel="pedidos"]'
            );

        if (!panel) {
            return;
        }

        if (
            ID(
                "v6HerramientasPedidos"
            )
        ) {
            return;
        }

        const header =
            panel.querySelector(
                ".admin-seccion-header"
            );

        const herramientas =
            document.createElement(
                "div"
            );

        herramientas.id =
            "v6HerramientasPedidos";

        herramientas.innerHTML = `

            <div
                class="v6-pedidos-toolbar"
            >

                <input
                    id="v6BuscarPedido"
                    type="search"
                    placeholder="
                        Buscar pedido,
                        cliente o producto...
                    "
                >

                <button
                    class="activo"
                    data-v6-filtro-pedido="todos"
                >
                    Todos
                </button>

                <button
                    data-v6-filtro-pedido="pendiente"
                >
                    Pendientes
                </button>

                <button
                    data-v6-filtro-pedido="preparando"
                >
                    Preparando
                </button>

                <button
                    data-v6-filtro-pedido="listo"
                >
                    Listos
                </button>

                <button
                    data-v6-filtro-pedido="entregado"
                >
                    Entregados
                </button>

                <button
                    data-v6-filtro-pedido="cancelado"
                >
                    Cancelados
                </button>

                <button
                    data-v6-exportar-pedidos
                >
                    Exportar
                </button>

            </div>
        `;

        header.after(
            herramientas
        );

        ID(
            "v6BuscarPedido"
        )
            ?.addEventListener(
                "input",
                evento => {

                    App.vendedor6
                        .busquedaPedido =
                        evento.target.value;

                    App.v6RenderPedidos();
                }
            );
    }

    /* ========================================================
       20. PEDIDOS
    ======================================================== */

    App.v6RenderPedidos =
        function () {

            prepararPedidos();

            const zona =
                ID(
                    "adminListaPedidos"
                );

            if (!zona) {
                return;
            }

            const filtro =
                App.vendedor6
                    .filtroPedido;

            const busqueda =
                normalizar(
                    App.vendedor6
                        .busquedaPedido
                );

            let lista =
                obtenerPedidos()
                    .slice()
                    .reverse();

            lista =
                lista.filter(
                    pedido => {

                        if (
                            filtro ===
                                "pendiente" &&
                            !pedidoPendiente(
                                pedido
                            )
                        ) {
                            return false;
                        }

                        if (
                            filtro ===
                                "preparando" &&
                            !pedidoPreparando(
                                pedido
                            )
                        ) {
                            return false;
                        }

                        if (
                            filtro ===
                                "listo" &&
                            !pedidoListo(
                                pedido
                            )
                        ) {
                            return false;
                        }

                        if (
                            filtro ===
                                "entregado" &&
                            !pedidoEntregado(
                                pedido
                            )
                        ) {
                            return false;
                        }

                        if (
                            filtro ===
                                "cancelado" &&
                            !pedidoCancelado(
                                pedido
                            )
                        ) {
                            return false;
                        }

                        if (busqueda) {

                            const nombresProductos =
                                (
                                    pedido.productos ||
                                    []
                                )
                                    .map(
                                        item =>
                                            item.nombre
                                    )
                                    .join(" ");

                            const texto =
                                normalizar([
                                    pedido.id,
                                    pedido.cliente
                                        ?.nombre,
                                    pedido.cliente
                                        ?.apellido,
                                    pedido.cliente
                                        ?.correo,
                                    pedido.cliente
                                        ?.telefono,
                                    nombresProductos
                                ].join(" "));

                            if (
                                !texto.includes(
                                    busqueda
                                )
                            ) {
                                return false;
                            }
                        }

                        return true;
                    }
                );

            if (!lista.length) {

                zona.innerHTML = `

                    <div
                        class="v6-vacio-grande"
                    >
                        <i
                            class="fa-solid fa-box-open"
                        ></i>

                        <h3>
                            No hay pedidos
                        </h3>

                        <p>
                            Cuando un cliente
                            confirme una compra,
                            aparecerá aquí.
                        </p>
                    </div>
                `;

                return;
            }

            zona.innerHTML =
                lista.map(
                    pedido =>
                        htmlPedido(
                            pedido
                        )
                ).join("");
        };

    function htmlPedido(pedido) {

        const cliente =
            `${pedido.cliente?.nombre || ""} ${
                pedido.cliente?.apellido || ""
            }`
                .trim() ||
            "Cliente";

        const items =
            Array.isArray(
                pedido.productos
            )
                ? pedido.productos
                : [];

        const resumen =
            items
                .slice(
                    0,
                    3
                )
                .map(
                    item =>
                        `${
                            numero(
                                item.cantidad
                            ) || 1
                        }× ${item.nombre}`
                )
                .join(" · ");

        return `

            <article
                class="v6-pedido-card"
            >

                <div
                    class="v6-pedido-cabecera"
                >

                    <div>
                        <span>
                            PEDIDO
                        </span>

                        <strong>
                            ${escapar(
                                pedido.id
                            )}
                        </strong>

                        <small>
                            ${escapar(
                                fechaBonita(
                                    pedido.fecha ||
                                    pedido.creado
                                )
                            )}
                        </small>
                    </div>

                    <span
                        class="v6-estado-pedido"
                    >
                        ${escapar(
                            pedido.estado ||
                            "Pendiente"
                        )}
                    </span>

                </div>


                <div
                    class="v6-cliente-pedido"
                >
                    <i
                        class="fa-solid fa-user"
                    ></i>

                    <div>
                        <strong>
                            ${escapar(
                                cliente
                            )}
                        </strong>

                        <small>
                            ${escapar(
                                pedido.cliente
                                    ?.correo ||
                                ""
                            )}
                        </small>
                    </div>
                </div>


                <div
                    class="v6-productos-pedido"
                >
                    ${
                        resumen
                            ? escapar(
                                resumen
                            )
                            : "Sin productos"
                    }
                </div>


                <div
                    class="v6-pedido-datos"
                >

                    <span>
                        <i
                            class="fa-solid fa-box"
                        ></i>

                        ${items.length}
                        productos
                    </span>

                    <span>
                        <i
                            class="fa-solid fa-wallet"
                        ></i>

                        ${escapar(
                            pedido.metodoPago ||
                            "No indicado"
                        )}
                    </span>

                    <strong>
                        ${dinero(
                            pedido.total
                        )}
                    </strong>

                </div>


                <div
                    class="v6-pedido-acciones"
                >

                    <button
                        data-v6-ver-pedido="${escapar(
                            pedido.id
                        )}"
                    >
                        <i
                            class="fa-solid fa-eye"
                        ></i>

                        Detalle
                    </button>

                    ${
                        pedidoPendiente(
                            pedido
                        )
                            ? `
                                <button
                                    data-v6-pedido-estado="${escapar(
                                        pedido.id
                                    )}"
                                    data-v6-nuevo-estado="Preparando"
                                >
                                    Preparar
                                </button>
                            `
                            : ""
                    }

                    ${
                        pedidoPreparando(
                            pedido
                        )
                            ? `
                                <button
                                    data-v6-pedido-estado="${escapar(
                                        pedido.id
                                    )}"
                                    data-v6-nuevo-estado="Listo para recojo"
                                >
                                    Listo
                                </button>
                            `
                            : ""
                    }

                    ${
                        pedidoListo(
                            pedido
                        )
                            ? `
                                <button
                                    data-v6-pedido-estado="${escapar(
                                        pedido.id
                                    )}"
                                    data-v6-nuevo-estado="Entregado"
                                >
                                    Entregado
                                </button>
                            `
                            : ""
                    }

                    ${
                        !pedidoEntregado(
                            pedido
                        ) &&
                        !pedidoCancelado(
                            pedido
                        )
                            ? `
                                <button
                                    class="peligro"
                                    data-v6-pedido-estado="${escapar(
                                        pedido.id
                                    )}"
                                    data-v6-nuevo-estado="Cancelado"
                                >
                                    Cancelar
                                </button>
                            `
                            : ""
                    }

                    <button
                        data-v6-imprimir-pedido="${escapar(
                            pedido.id
                        )}"
                    >
                        <i
                            class="fa-solid fa-print"
                        ></i>
                    </button>

                </div>

            </article>
        `;
    }

    /* ========================================================
       21. CAMBIAR ESTADO PEDIDO
    ======================================================== */

    function cambiarEstadoPedido(
        pedidoId,
        estado
    ) {

        const lista =
            obtenerPedidos();

        const pedido =
            lista.find(
                item =>
                    String(item.id) ===
                    String(pedidoId)
            );

        if (!pedido) {

            notificar(
                "Pedido no encontrado.",
                "error"
            );

            return;
        }

        pedido.estado =
            estado;

        pedido.actualizado =
            new Date()
                .toISOString();

        guardarPedidos(
            lista
        );

        App.v6RenderPedidos();

        App.v6RenderDashboard();

        notificar(
            `Pedido ${pedidoId}: ${estado}`
        );
    }

    /* ========================================================
       22. CLIENTES
    ======================================================== */

    function prepararClientes() {

        const panel =
            Q(
                '[data-admin-panel="clientes"]'
            );

        if (
            !panel ||
            ID(
                "v6HerramientasClientes"
            )
        ) {
            return;
        }

        const header =
            panel.querySelector(
                ".admin-seccion-header"
            );

        const herramientas =
            document.createElement(
                "div"
            );

        herramientas.id =
            "v6HerramientasClientes";

        herramientas.className =
            "v6-herramientas";

        herramientas.innerHTML = `

            <input
                id="v6BuscarCliente"
                type="search"
                placeholder="
                    Buscar cliente,
                    correo o teléfono...
                "
            >

            <button
                data-v6-exportar-clientes
            >
                Exportar clientes
            </button>
        `;

        header.after(
            herramientas
        );

        ID(
            "v6BuscarCliente"
        )
            ?.addEventListener(
                "input",
                evento => {

                    App.vendedor6
                        .busquedaCliente =
                        evento.target.value;

                    App.v6RenderClientes();
                }
            );
    }

    function construirClientes() {

        const mapa =
            new Map();

        obtenerUsuarios()
            .forEach(
                usuario => {

                    const rol =
                        normalizar(
                            usuario.rol
                        );

                    if (
                        rol &&
                        rol !== "cliente"
                    ) {
                        return;
                    }

                    const clave =
                        normalizar(
                            usuario.correo ||
                            usuario.email ||
                            usuario.id
                        );

                    if (!clave) {
                        return;
                    }

                    mapa.set(
                        clave,
                        {
                            nombre:
                                usuario.nombre ||
                                "",

                            apellido:
                                usuario.apellido ||
                                "",

                            correo:
                                usuario.correo ||
                                usuario.email ||
                                "",

                            telefono:
                                usuario.telefono ||
                                "",

                            pedidos:
                                0,

                            gastado:
                                0,

                            ultimaCompra:
                                null
                        }
                    );
                }
            );

        obtenerPedidos()
            .forEach(
                pedido => {

                    const correo =
                        normalizar(
                            pedido.cliente
                                ?.correo
                        );

                    const telefono =
                        normalizar(
                            pedido.cliente
                                ?.telefono
                        );

                    const clave =
                        correo ||
                        telefono ||
                        normalizar(
                            pedido.cliente
                                ?.nombre
                        );

                    if (!clave) {
                        return;
                    }

                    if (
                        !mapa.has(
                            clave
                        )
                    ) {

                        mapa.set(
                            clave,
                            {
                                nombre:
                                    pedido.cliente
                                        ?.nombre ||
                                    "Cliente",

                                apellido:
                                    pedido.cliente
                                        ?.apellido ||
                                    "",

                                correo:
                                    pedido.cliente
                                        ?.correo ||
                                    "",

                                telefono:
                                    pedido.cliente
                                        ?.telefono ||
                                    "",

                                pedidos:
                                    0,

                                gastado:
                                    0,

                                ultimaCompra:
                                    null
                            }
                        );
                    }

                    const cliente =
                        mapa.get(
                            clave
                        );

                    cliente.pedidos++;

                    if (
                        !pedidoCancelado(
                            pedido
                        )
                    ) {

                        cliente.gastado +=
                            numero(
                                pedido.total
                            );
                    }

                    const fecha =
                        pedido.fecha ||
                        pedido.creado;

                    if (
                        !cliente.ultimaCompra ||
                        new Date(fecha) >
                        new Date(
                            cliente.ultimaCompra
                        )
                    ) {

                        cliente.ultimaCompra =
                            fecha;
                    }
                }
            );

        return [
            ...mapa.values()
        ];
    }

    App.v6RenderClientes =
        function () {

            prepararClientes();

            const zona =
                ID(
                    "adminListaClientes"
                );

            if (!zona) {
                return;
            }

            const busqueda =
                normalizar(
                    App.vendedor6
                        .busquedaCliente
                );

            const clientes =
                construirClientes()
                    .filter(
                        cliente => {

                            if (!busqueda) {
                                return true;
                            }

                            const texto =
                                normalizar([
                                    cliente.nombre,
                                    cliente.apellido,
                                    cliente.correo,
                                    cliente.telefono
                                ].join(" "));

                            return texto
                                .includes(
                                    busqueda
                                );
                        }
                    )
                    .sort(
                        (a, b) =>
                            b.gastado -
                            a.gastado
                    );

            if (!clientes.length) {

                zona.innerHTML = `

                    <div
                        class="v6-vacio-grande"
                    >
                        <i
                            class="fa-solid fa-users"
                        ></i>

                        <h3>
                            No hay clientes
                        </h3>

                        <p>
                            Los clientes registrados
                            y compradores aparecerán
                            aquí.
                        </p>
                    </div>
                `;

                return;
            }

            zona.innerHTML = `

                <div
                    class="v6-clientes-grid"
                >

                    ${clientes.map(
                        cliente => `

                            <article
                                class="v6-cliente-card"
                            >

                                <div
                                    class="v6-cliente-avatar"
                                >
                                    ${escapar(
                                        String(
                                            cliente.nombre ||
                                            "C"
                                        )
                                            .charAt(0)
                                            .toUpperCase()
                                    )}
                                </div>

                                <div
                                    class="v6-cliente-info"
                                >
                                    <strong>
                                        ${escapar(
                                            `${cliente.nombre} ${cliente.apellido}`
                                                .trim()
                                        )}
                                    </strong>

                                    <span>
                                        ${escapar(
                                            cliente.correo ||
                                            "Sin correo"
                                        )}
                                    </span>

                                    <span>
                                        ${escapar(
                                            cliente.telefono ||
                                            "Sin teléfono"
                                        )}
                                    </span>
                                </div>

                                <div
                                    class="v6-cliente-stats"
                                >
                                    <div>
                                        <strong>
                                            ${cliente.pedidos}
                                        </strong>

                                        <span>
                                            Pedidos
                                        </span>
                                    </div>

                                    <div>
                                        <strong>
                                            ${dinero(
                                                cliente.gastado
                                            )}
                                        </strong>

                                        <span>
                                            Compras
                                        </span>
                                    </div>
                                </div>

                                <small>
                                    Última compra:
                                    ${
                                        cliente.ultimaCompra
                                            ? escapar(
                                                fechaBonita(
                                                    cliente.ultimaCompra
                                                )
                                            )
                                            : "Sin compras"
                                    }
                                </small>

                            </article>
                        `
                    ).join("")}

                </div>
            `;
        };

