    /* ============================================================
       14. EXPORTAR INVENTARIO / PRODUCTOS CSV
    ============================================================ */
    
    App.exportarInventarioCSV =
        function () {
    
            const productos =
                App.adminObtenerProductos();
    
            const filas = [
    
                [
                    "Producto",
                    "Codigo de barras",
                    "SKU",
                    "Categoria",
                    "Stock",
                    "Precio"
                ],
    
                ...productos.map(
                    producto => [
    
                        producto.nombre ||
                            "",
    
                        producto.codigoBarras ||
                        producto.codigo_barras ||
                            "",
    
                        producto.sku ||
                            "",
    
                        producto.categoria ||
                            "",
    
                        App.adminNumero(
                            producto.stock
                        ),
    
                        App.adminNumero(
                            producto.precio
                        )
    
                    ]
                )
    
            ];
    
    
            const csv =
                filas.map(
                    fila =>
                        fila.map(
                            valor =>
                                `"${String(valor)
                                    .replaceAll(
                                        '"',
                                        '""'
                                    )}"`
                        ).join(",")
                ).join("\n");
    
    
            const blob =
                new Blob(
                    [
                        "\uFEFF" +
                        csv
                    ],
                    {
                        type:
                            "text/csv;charset=utf-8"
                    }
                );
    
    
            const url =
                URL.createObjectURL(
                    blob
                );
    
    
            const enlace =
                document.createElement(
                    "a"
                );
    
            enlace.href =
                url;
    
            enlace.download =
                `inventario-emanuel-farma-${
                    new Date()
                        .toISOString()
                        .slice(0,10)
                }.csv`;
    
    
            document.body.appendChild(
                enlace
            );
    
            enlace.click();
    
            enlace.remove();
    
            URL.revokeObjectURL(
                url
            );
    
        };
    
    
    /* ============================================================
       15. IMPORTAR INVENTARIO
    ============================================================ */
    
    App.importarInventarioAdmin =
        function () {
    
            let input =
                App.adminId(
                    "inputImportarInventario"
                );
    
            if (!input) {
    
                input =
                    document.createElement(
                        "input"
                    );
    
                input.id =
                    "inputImportarInventario";
    
                input.type =
                    "file";
    
                input.accept =
                    ".csv";
    
                input.hidden =
                    true;
    
                document.body.appendChild(
                    input
                );
    
    
                input.addEventListener(
                    "change",
                    async () => {
    
                        const archivo =
                            input.files?.[0];
    
                        if (!archivo) {
                            return;
                        }
    
    
                        const texto =
                            await archivo.text();
    
    
                        const lineas =
                            texto
                                .split(
                                    /\r?\n/
                                )
                                .filter(Boolean);
    
    
                        if (
                            lineas.length < 2
                        ) {
    
                            App.adminAvisar(
                                "El archivo está vacío.",
                                "error"
                            );
    
                            return;
    
                        }
    
    
                        let actualizados = 0;
    
    
                        lineas
                            .slice(1)
                            .forEach(linea => {
    
                                /*
                                 * Importación sencilla:
                                 * busca primero por código
                                 * y luego por SKU.
                                 */
    
                                const columnas =
                                    linea
                                        .split(",")
                                        .map(
                                            item =>
                                                item
                                                    .replace(
                                                        /^"|"$/g,
                                                        ""
                                                    )
                                                    .replaceAll(
                                                        '""',
                                                        '"'
                                                    )
                                        );
    
    
                                const codigo =
                                    columnas[1];
    
                                const sku =
                                    columnas[2];
    
                                const stock =
                                    Number(
                                        columnas[4]
                                    );
    
    
                                const producto =
                                    App.adminObtenerProductos()
                                        .find(item =>
    
                                            String(
                                                item.codigoBarras ||
                                                item.codigo_barras ||
                                                ""
                                            ) ===
                                                String(
                                                    codigo
                                                )
    
                                            ||
    
                                            (
                                                sku &&
                                                String(
                                                    item.sku ||
                                                    ""
                                                ) ===
                                                    String(
                                                        sku
                                                    )
                                            )
    
                                        );
    
    
                                if (
                                    producto &&
                                    Number.isFinite(
                                        stock
                                    )
                                ) {
    
                                    producto.stock =
                                        stock;
    
                                    actualizados++;
    
                                }
    
                            });
    
    
                        App.renderInventarioAdmin();
                        App.renderAdminDashboard();
    
    
                        App.adminAvisar(
                            `${actualizados} productos actualizados.`
                        );
    
    
                        input.value =
                            "";
    
                    }
                );
    
            }
    
    
            input.click();
    
        };
    
    
    /* ============================================================
       16. PEDIDOS
    ============================================================ */
    
    App.renderPedidosAdmin =
        function () {
    
            const contenedor =
                App.adminId(
                    "adminListaPedidos"
                );
    
            if (!contenedor) {
                return;
            }
    
    
            const buscar =
                App.adminNormalizar(
                    App.adminId(
                        "adminBuscarPedido"
                    )?.value || ""
                );
    
    
            const filtro =
                App.adminNormalizar(
                    App.adminId(
                        "adminFiltroPedido"
                    )?.value || "todos"
                );
    
    
            let pedidos =
                App.adminPedidosSucursal(
                    App.adminObtenerPedidos()
                );
    
    
            if (buscar) {
    
                pedidos =
                    pedidos.filter(
                        pedido => {
    
                            const texto =
                                App.adminNormalizar([
    
                                    pedido.id,
                                    pedido.estado,
                                    pedido.cliente
                                        ?.nombre,
                                    pedido.cliente
                                        ?.correo,
                                    pedido.cliente
                                        ?.telefono,
    
                                    ...(pedido.productos ||
                                        [])
                                        .map(
                                            producto =>
                                                producto.nombre
                                        )
    
                                ].join(" "));
    
    
                            return texto.includes(
                                buscar
                            );
    
                        }
                    );
    
            }
    
    
            if (
                filtro !== "todos"
            ) {
    
                pedidos =
                    pedidos.filter(
                        pedido =>
                            App.adminNormalizar(
                                pedido.estado
                            ).includes(
                                filtro
                            )
                    );
    
            }
    
    
            const todos =
                App.adminPedidosSucursal(
                    App.adminObtenerPedidos()
                );
    
    
            const contarEstado =
                palabra =>
    
                    todos.filter(
                        pedido =>
                            App.adminNormalizar(
                                pedido.estado
                            ).includes(
                                palabra
                            )
                    ).length;
    
    
            const poner =
                (
                    id,
                    valor
                ) => {
    
                    const elemento =
                        App.adminId(id);
    
                    if (elemento) {
                        elemento.textContent =
                            valor;
                    }
    
                };
    
    
            poner(
                "pedidosTotal",
                todos.length
            );
    
            poner(
                "pedidosPendientes",
                contarEstado(
                    "pendiente"
                )
            );
    
            poner(
                "pedidosPreparando",
                contarEstado(
                    "preparando"
                )
            );
    
            poner(
                "pedidosListos",
                contarEstado(
                    "listo"
                )
            );
    
    
            if (!pedidos.length) {
    
                contenedor.innerHTML = `
    
                    <div class="estado-vacio">
    
                        <i class="fa-solid fa-receipt"></i>
    
                        <h3>
                            No hay pedidos
                        </h3>
    
                        <p>
                            Los pedidos de clientes
                            aparecerán aquí.
                        </p>
    
                    </div>
    
                `;
    
                return;
    
            }
    
    
            contenedor.innerHTML =
                pedidos.map(
                    pedido => {
    
                        const productos =
                            pedido.productos ||
                            [];
    
    
                        return `
    
                            <article
                                class="admin-card pedido-admin"
                            >
    
                                <div
                                    class="admin-card-header"
                                >
    
                                    <div>
    
                                        <strong>
                                            ${
                                                App.adminEscape(
                                                    pedido.id ||
                                                    "Pedido"
                                                )
                                            }
                                        </strong>
    
                                        <p>
                                            ${
                                                App.adminFecha(
                                                    pedido.fecha
                                                )
                                            }
                                        </p>
    
                                    </div>
    
    
                                    <strong>
                                        ${
                                            App.adminPrecio(
                                                pedido.total
                                            )
                                        }
                                    </strong>
    
                                </div>
    
    
                                <p>
    
                                    <strong>
                                        Cliente:
                                    </strong>
    
                                    ${
                                        App.adminEscape(
                                            pedido.cliente
                                                ?.nombre ||
                                            pedido.cliente
                                                ?.correo ||
                                            "Cliente"
                                        )
                                    }
    
                                </p>
    
    
                                <p>
    
                                    <strong>
                                        Pago:
                                    </strong>
    
                                    ${
                                        App.adminEscape(
                                            pedido.metodoPago ||
                                            "—"
                                        )
                                    }
    
                                </p>
    
    
                                <p>
    
                                    <strong>
                                        Sucursal:
                                    </strong>
    
                                    ${
                                        App.adminEscape(
                                            pedido.sucursalNombre ||
                                            App.adminSucursalActual()
                                                .nombre
                                        )
                                    }
    
                                </p>
    
    
                                <p>
    
                                    <strong>
                                        Estado:
                                    </strong>
    
                                    ${
                                        App.adminEscape(
                                            pedido.estado ||
                                            "Pendiente"
                                        )
                                    }
    
                                </p>
    
    
                                <p>
    
                                    <strong>
                                        Productos:
                                    </strong>
    
                                    ${
                                        productos
                                            .map(
                                                producto =>
                                                    `${
                                                        App.adminEscape(
                                                            producto.nombre
                                                        )
                                                    } × ${
                                                        App.adminNumero(
                                                            producto.cantidad
                                                        )
                                                    }`
                                            )
                                            .join(", ")
                                    }
    
                                </p>
    
    
                                <div
                                    style="
                                        display:flex;
                                        gap:8px;
                                        flex-wrap:wrap;
                                        margin-top:14px;
                                    "
                                >
    
                                    <button
                                        type="button"
                                        data-pedido-id="${
                                            App.adminEscape(
                                                pedido.id
                                            )
                                        }"
                                        data-pedido-estado="Preparando"
                                    >
                                        Preparando
                                    </button>
    
    
                                    <button
                                        type="button"
                                        data-pedido-id="${
                                            App.adminEscape(
                                                pedido.id
                                            )
                                        }"
                                        data-pedido-estado="Listo para recojo"
                                    >
                                        Listo
                                    </button>
    
    
                                    <button
                                        type="button"
                                        data-pedido-id="${
                                            App.adminEscape(
                                                pedido.id
                                            )
                                        }"
                                        data-pedido-estado="Entregado"
                                    >
                                        Entregado
                                    </button>
    
    
                                    <button
                                        type="button"
                                        data-pedido-id="${
                                            App.adminEscape(
                                                pedido.id
                                            )
                                        }"
                                        data-pedido-estado="Archivado"
                                    >
                                        Archivar
                                    </button>
    
                                </div>
    
                            </article>
    
                        `;
    
                    }).join("");
    
        };
    
    
    App.actualizarEstadoPedidoAdmin =
        function (
            pedidoId,
            estado
        ) {
    
            const pedidos =
                App.adminObtenerPedidos();
    
            const pedido =
                pedidos.find(
                    item =>
                        String(
                            item.id
                        ) ===
                        String(
                            pedidoId
                        )
                );
    
            if (!pedido) {
    
                App.adminAvisar(
                    "No encontramos el pedido.",
                    "error"
                );
    
                return;
    
            }
    
    
            pedido.estado =
                estado;
    
            pedido.fechaActualizacion =
                new Date()
                    .toISOString();
    
    
            if (!pedido.sucursal) {
    
                pedido.sucursal =
                    App.parte5.sucursal;
    
                pedido.sucursalNombre =
                    App.adminSucursalActual()
                        .nombre;
    
            }
    
    
            App.adminGuardarPedidos(
                pedidos
            );
    
            App.renderPedidosAdmin();
            App.renderAdminDashboard();
    
            App.adminAvisar(
                `Pedido: ${estado}`
            );
    
        };
    
    
    /* ============================================================
       17. CLIENTES
    ============================================================ */
    
    App.renderClientesAdmin =
        function () {
    
            const contenedor =
                App.adminId(
                    "adminListaClientes"
                );
    
            if (!contenedor) {
                return;
            }
    
    
            const usuarios =
                App.adminObtenerUsuarios()
    
                    .filter(usuario => {
    
                        const rol =
                            App.adminNormalizar(
                                usuario.rol ||
                                "cliente"
                            );
    
                        return (
                            !usuario.rol ||
                            rol === "cliente"
                        );
    
                    });
    
    
            const pedidos =
                App.adminObtenerPedidos();
    
    
            const buscar =
                App.adminNormalizar(
                    App.adminId(
                        "adminBuscarCliente"
                    )?.value || ""
                );
    
    
            const filtro =
                App.adminId(
                    "adminFiltroCliente"
                )?.value || "todos";
    
    
            let clientes =
                usuarios.map(usuario => {
    
                    const pedidosCliente =
                        pedidos.filter(
                            pedido => {
    
                                const correoPedido =
                                    App.adminNormalizar(
                                        pedido.cliente
                                            ?.correo ||
                                        ""
                                    );
    
                                const correoUsuario =
                                    App.adminNormalizar(
                                        usuario.correo ||
                                        ""
                                    );
    
    
                                return (
    
                                    correoPedido &&
                                    correoPedido ===
                                        correoUsuario
    
                                ) || (
    
                                    pedido.usuarioId &&
                                    String(
                                        pedido.usuarioId
                                    ) ===
                                    String(
                                        usuario.id ||
                                        usuario.correo
                                    )
    
                                );
    
                            }
                        );
    
    
                    return {
    
                        ...usuario,
    
                        cantidadPedidos:
                            pedidosCliente.length,
    
                        totalComprado:
                            App.adminVentas(
                                pedidosCliente
                            )
    
                    };
    
                });
    
    
            if (buscar) {
    
                clientes =
                    clientes.filter(
                        cliente =>
    
                            App.adminNormalizar([
    
                                cliente.nombre,
                                cliente.correo,
                                cliente.telefono
    
                            ].join(" "))
                            .includes(
                                buscar
                            )
                    );
    
            }
    
    
            if (
                filtro ===
                "con-pedidos"
            ) {
    
                clientes =
                    clientes.filter(
                        cliente =>
                            cliente
                                .cantidadPedidos >
                            0
                    );
    
            }
    
    
            if (
                filtro ===
                "sin-pedidos"
            ) {
    
                clientes =
                    clientes.filter(
                        cliente =>
                            cliente
                                .cantidadPedidos ===
                            0
                    );
    
            }
    
    
            if (
                filtro ===
                "frecuentes"
            ) {
    
                clientes =
                    clientes.filter(
                        cliente =>
                            cliente
                                .cantidadPedidos >=
                            3
                    );
    
            }
    
    
            const poner =
                (
                    id,
                    valor
                ) => {
    
                    const elemento =
                        App.adminId(id);
    
                    if (elemento) {
                        elemento.textContent =
                            valor;
                    }
    
                };
    
    
            poner(
                "clientesKpiTotal",
                usuarios.length
            );
    
    
            poner(
                "clientesKpiCompradores",
    
                clientes.filter(
                    cliente =>
                        cliente
                            .cantidadPedidos >
                        0
                ).length
            );
    
    
            poner(
                "clientesKpiPedidos",
                pedidos.length
            );
    
    
            poner(
                "clientesKpiVentas",
                App.adminPrecio(
                    App.adminVentas(
                        pedidos
                    )
                )
            );
    
    
            if (!clientes.length) {
    
                contenedor.innerHTML = `
    
                    <div class="estado-vacio">
                        No encontramos clientes.
                    </div>
    
                `;
    
                return;
    
            }
    
    
            contenedor.innerHTML =
                clientes.map(
                    cliente => `
    
                        <article class="admin-card">
    
                            <div class="admin-card-header">
    
                                <div>
    
                                    <strong>
                                        ${
                                            App.adminEscape(
                                                cliente.nombre ||
                                                "Cliente"
                                            )
                                        }
                                    </strong>
    
                                    <p>
                                        ${
                                            App.adminEscape(
                                                cliente.correo ||
                                                ""
                                            )
                                        }
                                    </p>
    
                                </div>
    
    
                                <strong>
                                    ${
                                        cliente
                                            .cantidadPedidos
                                    } pedidos
                                </strong>
    
                            </div>
    
    
                            <p>
    
                                Teléfono:
                                ${
                                    App.adminEscape(
                                        cliente.telefono ||
                                        "No registrado"
                                    )
                                }
    
                            </p>
    
    
                            <p>
    
                                Compras:
                                <strong>
                                    ${
                                        App.adminPrecio(
                                            cliente
                                                .totalComprado
                                        )
                                    }
                                </strong>
    
                            </p>
    
                        </article>
    
                    `
                ).join("");
    
        };
    
    
    /* ============================================================
       18. MAYORISTAS
    ============================================================ */
    
    App.obtenerMayoristasAdmin =
        function () {
    
            return App.adminLeer(
                App.adminClaves.mayoristas,
                []
            );
    
        };
    
    
    App.guardarMayoristasAdmin =
        function (mayoristas) {
    
            App.adminGuardar(
                App.adminClaves.mayoristas,
                mayoristas
            );
    
        };
    
    
    App.obtenerSolicitudesMayoristas =
        function () {
    
            return App.adminLeer(
                App.adminClaves
                    .solicitudesMayoristas,
                []
            );
    
        };
    
    
    App.guardarSolicitudesMayoristas =
        function (solicitudes) {
    
            App.adminGuardar(
                App.adminClaves
                    .solicitudesMayoristas,
                solicitudes
            );
    
        };
    
    
    App.crearCuentaMayoristaAdmin =
        function () {
    
            const empresa =
                App.adminId(
                    "nuevoMayoristaEmpresa"
                )?.value.trim();
    
            const ruc =
                App.adminId(
                    "nuevoMayoristaRuc"
                )?.value.trim();
    
            const responsable =
                App.adminId(
                    "nuevoMayoristaResponsable"
                )?.value.trim();
    
            const telefono =
                App.adminId(
                    "nuevoMayoristaTelefono"
                )?.value.trim();
    
            const correo =
                App.adminNormalizar(
                    App.adminId(
                        "nuevoMayoristaCorreo"
                    )?.value || ""
                );
    
            const password =
                App.adminId(
                    "nuevoMayoristaPassword"
                )?.value || "";
    
    
            if (
                !empresa ||
                !correo ||
                !password
            ) {
    
                App.adminAvisar(
                    "Completa empresa, correo y contraseña.",
                    "error"
                );
    
                return;
    
            }
    
    
            const usuarios =
                App.adminObtenerUsuarios();
    
    
            if (
                usuarios.some(
                    usuario =>
                        App.adminNormalizar(
                            usuario.correo
                        ) ===
                        correo
                )
            ) {
    
                App.adminAvisar(
                    "Ya existe una cuenta con ese correo.",
                    "error"
                );
    
                return;
    
            }
    
    
            const id =
                `MAY-${Date.now()}`;
    
    
            const usuario = {
    
                id,
    
                nombre:
                    responsable ||
                    empresa,
    
                empresa,
    
                ruc,
    
                telefono,
    
                correo,
    
                password,
    
                rol:
                    "mayorista",
    
                activo:
                    true,
    
                autorizado:
                    true,
    
                fechaRegistro:
                    new Date()
                        .toISOString()
    
            };
    
    
            usuarios.push(
                usuario
            );
    
    
            App.adminGuardarUsuarios(
                usuarios
            );
    
    
            const mayoristas =
                App.obtenerMayoristasAdmin();
    
    
            mayoristas.unshift({
    
                id,
    
                usuarioId:
                    id,
    
                empresa,
    
                ruc,
    
                responsable,
    
                telefono,
    
                correo,
    
                activo:
                    true,
    
                fechaCreacion:
                    new Date()
                        .toISOString()
    
            });
    
    
            App.guardarMayoristasAdmin(
                mayoristas
            );
    
    
            [
                "nuevoMayoristaEmpresa",
                "nuevoMayoristaRuc",
                "nuevoMayoristaResponsable",
                "nuevoMayoristaTelefono",
                "nuevoMayoristaCorreo",
                "nuevoMayoristaPassword"
            ].forEach(idCampo => {
    
                const campo =
                    App.adminId(
                        idCampo
                    );
    
                if (campo) {
                    campo.value = "";
                }
    
            });
    
    
            App.renderMayoristasAdmin();
    
    
            App.adminAvisar(
                `Cuenta mayorista creada para ${empresa}.`
            );
    
        };
    
    
    App.renderMayoristasAdmin =
        function () {
    
            const contenedor =
                App.adminId(
                    "adminListaMayoristas"
                );
    
            if (!contenedor) {
                return;
            }
    
    
            const mayoristas =
                App.obtenerMayoristasAdmin();
    
            const solicitudes =
                App.obtenerSolicitudesMayoristas();
    
    
            const buscar =
                App.adminNormalizar(
                    App.adminId(
                        "adminBuscarMayorista"
                    )?.value || ""
                );
    
    
            const filtrados =
                mayoristas.filter(
                    mayorista => {
    
                        if (!buscar) {
                            return true;
                        }
    
                        return App.adminNormalizar([
    
                            mayorista.empresa,
                            mayorista.ruc,
                            mayorista.responsable,
                            mayorista.correo
    
                        ].join(" "))
                        .includes(
                            buscar
                        );
    
                    }
                );
    
    
            const pendientes =
                solicitudes.filter(
                    solicitud =>
                        App.adminNormalizar(
                            solicitud.estado ||
                            "pendiente"
                        ) ===
                        "pendiente"
                );
    
    
            const poner =
                (
                    id,
                    valor
                ) => {
    
                    const elemento =
                        App.adminId(id);
    
                    if (elemento) {
                        elemento.textContent =
                            valor;
                    }
    
                };
    
    
            poner(
                "mayoristasKpiEmpresas",
                mayoristas.length
            );
    
            poner(
                "mayoristasKpiPendientes",
                pendientes.length
            );
    
    
            const htmlSolicitudes =
                pendientes.length
                    ? `
    
                        <h3>
                            Solicitudes pendientes
                        </h3>
    
                        ${
                            pendientes.map(
                                solicitud => `
    
                                    <article
                                        class="admin-card"
                                    >
    
                                        <strong>
                                            ${
                                                App.adminEscape(
                                                    solicitud.empresa ||
                                                    "Empresa"
                                                )
                                            }
                                        </strong>
    
                                        <p>
                                            Responsable:
                                            ${
                                                App.adminEscape(
                                                    solicitud.responsable ||
                                                    ""
                                                )
                                            }
                                        </p>
    
                                        <p>
                                            RUC:
                                            ${
                                                App.adminEscape(
                                                    solicitud.ruc ||
                                                    "—"
                                                )
                                            }
                                        </p>
    
                                        <p>
                                            Correo:
                                            ${
                                                App.adminEscape(
                                                    solicitud.correo ||
                                                    ""
                                                )
                                            }
                                        </p>
    
                                        <button
                                            type="button"
                                            data-aprobar-mayorista="${
                                                App.adminEscape(
                                                    solicitud.id
                                                )
                                            }"
                                        >
                                            Aprobar solicitud
                                        </button>
    
                                    </article>
    
                                `
                            ).join("")
                        }
    
                        <hr>
    
                    `
                    : "";
    
    
            const htmlCuentas =
                filtrados.length
                    ? filtrados.map(
                        mayorista => `
    
                            <article
                                class="admin-card"
                            >
    
                                <div
                                    class="admin-card-header"
                                >
    
                                    <div>
    
                                        <strong>
                                            ${
                                                App.adminEscape(
                                                    mayorista.empresa
                                                )
                                            }
                                        </strong>
    
                                        <p>
                                            RUC:
                                            ${
                                                App.adminEscape(
                                                    mayorista.ruc ||
                                                    "—"
                                                )
                                            }
                                        </p>
    
                                    </div>
    
    
                                    <strong>
                                        ${
                                            mayorista.activo !==
                                            false
                                                ? "Activo"
                                                : "Bloqueado"
                                        }
                                    </strong>
    
                                </div>
    
    
                                <p>
    
                                    Responsable:
                                    ${
                                        App.adminEscape(
                                            mayorista.responsable ||
                                            "—"
                                        )
                                    }
    
                                </p>
    
    
                                <p>
    
                                    Usuario:
                                    <strong>
                                        ${
                                            App.adminEscape(
                                                mayorista.correo
                                            )
                                        }
                                    </strong>
    
                                </p>
    
    
                                <div
                                    style="
                                        display:flex;
                                        gap:8px;
                                        flex-wrap:wrap;
                                    "
                                >
    
                                    <button
                                        type="button"
                                        data-toggle-mayorista="${
                                            App.adminEscape(
                                                mayorista.id
                                            )
                                        }"
                                    >
    
                                        ${
                                            mayorista.activo !==
                                            false
                                                ? "Bloquear"
                                                : "Activar"
                                        }
    
                                    </button>
    
    
                                    <button
                                        type="button"
                                        data-password-mayorista="${
                                            App.adminEscape(
                                                mayorista.id
                                            )
                                        }"
                                    >
                                        Cambiar contraseña
                                    </button>
    
                                </div>
    
                            </article>
    
                        `
                    ).join("")
                    : `
    
                        <div class="estado-vacio">
    
                            Todavía no hay
                            cuentas mayoristas.
    
                        </div>
    
                    `;
    
    
            contenedor.innerHTML =
                htmlSolicitudes +
                `
    
                    <h3>
                        Cuentas autorizadas
                    </h3>
    
                    ${htmlCuentas}
    
                `;
    
        };
    
    
    App.aprobarSolicitudMayorista =
        function (id) {
    
            const solicitudes =
                App.obtenerSolicitudesMayoristas();
    
            const solicitud =
                solicitudes.find(
                    item =>
                        String(item.id) ===
                        String(id)
                );
    
            if (!solicitud) {
                return;
            }
    
    
            const campos = {
    
                nuevoMayoristaEmpresa:
                    solicitud.empresa,
    
                nuevoMayoristaRuc:
                    solicitud.ruc,
    
                nuevoMayoristaResponsable:
                    solicitud.responsable,
    
                nuevoMayoristaTelefono:
                    solicitud.telefono,
    
                nuevoMayoristaCorreo:
                    solicitud.correo
    
            };
    
    
            Object.entries(
                campos
            ).forEach(
                ([idCampo, valor]) => {
    
                    const campo =
                        App.adminId(
                            idCampo
                        );
    
                    if (campo) {
    
                        campo.value =
                            valor || "";
    
                    }
    
                }
            );
    
    
            solicitud.estado =
                "en-revision";
    
    
            App.guardarSolicitudesMayoristas(
                solicitudes
            );
    
    
            App.renderMayoristasAdmin();
    
    
            App.adminId(
                "nuevoMayoristaPassword"
            )?.focus();
    
    
            App.adminAvisar(
                "Solicitud cargada. Asigna una contraseña y pulsa Crear cuenta."
            );
    
        };
    
    
    App.alternarMayoristaAdmin =
        function (id) {
    
            const mayoristas =
                App.obtenerMayoristasAdmin();
    
            const mayorista =
                mayoristas.find(
                    item =>
                        String(item.id) ===
                        String(id)
                );
    
            if (!mayorista) {
                return;
            }
    
    
            mayorista.activo =
                mayorista.activo ===
                false;
    
    
            App.guardarMayoristasAdmin(
                mayoristas
            );
    
    
            const usuarios =
                App.adminObtenerUsuarios();
    
            const usuario =
                usuarios.find(
                    item =>
                        String(item.id) ===
                        String(
                            mayorista.usuarioId
                        )
                );
    
    
            if (usuario) {
    
                usuario.activo =
                    mayorista.activo;
    
                App.adminGuardarUsuarios(
                    usuarios
                );
    
            }
    
    
            App.renderMayoristasAdmin();
    
        };
    
    
    App.cambiarPasswordMayoristaAdmin =
        function (id) {
    
            const mayorista =
                App.obtenerMayoristasAdmin()
                    .find(
                        item =>
                            String(item.id) ===
                            String(id)
                    );
    
            if (!mayorista) {
                return;
            }
    
    
            const password =
                prompt(
                    `Nueva contraseña para ${mayorista.empresa}:`
                );
    
    
            if (!password) {
                return;
            }
    
    
            const usuarios =
                App.adminObtenerUsuarios();
    
            const usuario =
                usuarios.find(
                    item =>
                        String(item.id) ===
                        String(
                            mayorista.usuarioId
                        )
                );
    
    
            if (!usuario) {
    
                App.adminAvisar(
                    "No encontramos el usuario.",
                    "error"
                );
    
                return;
    
            }
    
    
            usuario.password =
                password;
    
    
            App.adminGuardarUsuarios(
                usuarios
            );
    
    
            App.adminAvisar(
                "Contraseña actualizada."
            );
    
        };
    
    
